SELECT ARRAY_AGG(v) FROM (VALUES 3,NULL,1,3) t(v);
SELECT ARRAY_AGG(DISTINCT v) FROM (VALUES 3,NULL,1,3) t(v);
SELECT ARRAY_AGG(v ORDER BY v NULLS LAST) FROM (VALUES 3,NULL,1,3) t(v);
SELECT ARRAY_AGG(v ORDER BY v DESC NULLS FIRST) FROM (VALUES 3,NULL,1,3) t(v);
SELECT ARRAY_AGG(DISTINCT v ORDER BY v DESC) FROM (VALUES 3,NULL,1,3) t(v);
SELECT ARRAY_AGG(v ORDER BY 1 DESC) FROM (VALUES 1,2) t(v);
SELECT ARRAY_AGG(DISTINCT a ORDER BY b) FROM (VALUES (4,3),(5,1),(5,2)) t(a,b);
SELECT ARRAY_AGG(DISTINCT a ORDER BY b) FROM (VALUES (3,1),(1,1),(2,1)) t(a,b);
SELECT ARRAY_AGG(v) FROM (VALUES 1) t(v) WHERE FALSE;
SELECT ARRAY_AGG(v) FROM (VALUES CAST(NULL AS INT)) t(v);
SELECT CASE WHEN TRUE THEN v ELSE 1/0 END AS v FROM (VALUES 1,2) t(v);
SELECT CASE WHEN TRUE THEN v ELSE ARRAY_AGG(v) END FROM (VALUES 1,2) t(v);
SELECT CASE WHEN FALSE THEN ARRAY_AGG(v) ELSE 1 END AS v FROM (VALUES 1,2) t(v);
SELECT CASE WHEN TRUE THEN 1 ELSE ARRAY_AGG(v) END AS v FROM (VALUES 1,2) t(v) WHERE FALSE;
SELECT ARRAY_AGG(4/v ORDER BY v) FILTER(WHERE v<>0) FROM (VALUES 0,2,4) t(v);
SELECT COUNT(*) FILTER(WHERE v>0),SUM(v) FILTER(WHERE v>0),AVG(v) FILTER(WHERE v>0),MIN(v) FILTER(WHERE v>0),MAX(v) FILTER(WHERE v>0) FROM (VALUES NULL,0,1,2) t(v);
SELECT COUNT(*) FILTER(WHERE FALSE),ARRAY_AGG(v) FILTER(WHERE FALSE) FROM (VALUES 1,2) t(v);
SELECT ARRAY_AGG(SUM(v)) FROM (VALUES 1,2) t(v);
SELECT ARRAY_AGG(v) FILTER(WHERE COUNT(*)>0) FROM (VALUES 1,2) t(v);
SELECT ARRAY_AGG(v ORDER BY SUM(v)) FROM (VALUES 1,2) t(v);
SELECT ARRAY_AGG(v) FROM (VALUES 1) t(v) WHERE ARRAY_AGG(v)=ARRAY[1];
SELECT g,ARRAY_AGG(v ORDER BY v DESC) AS a FROM (VALUES ('a',1),('a',2),('b',3)) t(g,v) GROUP BY g HAVING CARDINALITY(ARRAY_AGG(v))>1 ORDER BY g;
SELECT ARRAY_AGG((SELECT MAX(x) FROM SYSTEM_RANGE(1,3) WHERE x<=v) ORDER BY v) AS a FROM (VALUES 2,3) t(v);
SELECT ARRAY_AGG(v),g FROM (VALUES ('a',1),('b',2)) t(g,v);
SELECT ARRAY_AGG(v ORDER BY missing) FROM (VALUES 1) t(v) WHERE FALSE;
SELECT ARRAY_AGG(ARRAY[v,v+1] ORDER BY v DESC) FROM (VALUES 1,2) t(v);
SELECT ARRAY_AGG(v) FROM (VALUES 1.00,2.25) t(v);
SELECT ARRAY_AGG(1.5+2.25) FROM (VALUES 1,2) t(v);
SELECT ARRAY_AGG(v) FROM (VALUES 1.5+2.25,2.25) t(v);
SELECT ARRAY_AGG(1/0) FILTER(WHERE FALSE) FROM (VALUES 1) t(v);
SELECT COUNT(1/0) FILTER(WHERE FALSE) FROM (VALUES 1) t(v);
SELECT SUM(v) FILTER(WHERE 'bad') FROM (VALUES 1) t(v) WHERE FALSE;
SELECT ARRAY_AGG(v ORDER BY v) FROM (VALUES X'00',NULL,X'ff') t(v);
SELECT ARRAY_AGG(DISTINCT v) FROM (VALUES TIME WITH TIME ZONE '12:00:00+03',TIME WITH TIME ZONE '09:00:00Z',NULL) t(v);
SELECT * FROM UNNEST();
SELECT * FROM UNNEST(ARRAY[]);
SELECT * FROM UNNEST(ARRAY[1,2,3]);
CALL UNNEST(ARRAY[1,2,3]);
SELECT * FROM UNNEST(ARRAY[1],ARRAY[2,3,4],ARRAY[5,6]);
SELECT * FROM UNNEST(ARRAY[1],ARRAY[2,3,4],ARRAY[5,6]) WITH ORDINALITY;
SELECT v,n FROM (UNNEST(ARRAY[1,2]) WITH ORDINALITY) t(v,n) ORDER BY n;
SELECT * FROM UNNEST(NULL);
SELECT CAST(1 AS NULL),CAST(ARRAY[1,2] AS NULL ARRAY);
SELECT * FROM UNNEST(CAST(NULL AS INT ARRAY)) WITH ORDINALITY;
SELECT * FROM UNNEST(1);
SELECT * FROM UNNEST(ROW(1,'a',NULL));
SELECT * FROM UNNEST(ARRAY[ARRAY[1,2],ARRAY[3]]);
SELECT * FROM UNNEST(ARRAY[1]||ARRAY[2]);
SELECT * FROM UNNEST(COALESCE(ARRAY[1],ARRAY[2]));
SELECT * FROM UNNEST(CAST(ARRAY[1] AS SMALLINT ARRAY));
SELECT * FROM UNNEST((SELECT ARRAY[1,2]));
SELECT * FROM UNNEST(ARRAY(SELECT x FROM SYSTEM_RANGE(1,3)));
SELECT * FROM UNNEST((SELECT ARRAY_AGG(x ORDER BY x) FROM SYSTEM_RANGE(1,3)));
SELECT 1 IN(SELECT * FROM UNNEST(ARRAY[1,2,3])) AS v;
SELECT 4 IN(SELECT * FROM UNNEST(ARRAY[1,2,3])) AS v;
SELECT x FROM SYSTEM_RANGE(1,5) WHERE x IN(SELECT * FROM UNNEST(ARRAY[2,4])) ORDER BY x;
SELECT a.c1,b.c1 FROM UNNEST(ARRAY[1,2]) a CROSS JOIN UNNEST(ARRAY[3]) b ORDER BY a.c1;
SELECT * FROM (VALUES ARRAY[1]) t(a),UNNEST(t.a);
CREATE TABLE unknown_type AS SELECT * FROM UNNEST(1);
TABLE unknown_type;
DROP TABLE unknown_type;
WITH q(a) AS (VALUES ARRAY[2,1]) SELECT ARRAY_AGG(v ORDER BY v) AS a FROM UNNEST((SELECT a FROM q)) t(v);
CREATE TABLE source(g VARCHAR,v INT);
INSERT INTO source VALUES('a',1),('a',2),('b',3),('b',NULL);
CREATE TABLE collected AS SELECT g,ARRAY_AGG(v ORDER BY v DESC) AS a FROM source GROUP BY g;
TABLE collected ORDER BY g;
CREATE TABLE defaults(a INT ARRAY DEFAULT (SELECT ARRAY_AGG(v ORDER BY v NULLS LAST) FILTER(WHERE g='a') FROM source));
INSERT INTO defaults DEFAULT VALUES;
INSERT INTO source VALUES('a',4);
INSERT INTO defaults DEFAULT VALUES;
TABLE defaults;
DROP TABLE source;
CREATE TABLE expanded AS SELECT * FROM UNNEST(ARRAY[1,2],ARRAY['a']) WITH ORDINALITY;
TABLE expanded ORDER BY nord;
SELECT ARRAY_AGG(c1 ORDER BY nord) AS a FROM expanded;
DROP TABLE defaults,collected,expanded,source;
